package br.com.strumlab.analysis;
import java.util.*;
import java.nio.charset.StandardCharsets;
import java.security.*;
import org.springframework.stereotype.Service;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.annotation.Transactional;
import tools.jackson.databind.ObjectMapper;
import br.com.strumlab.songs.*;
import static br.com.strumlab.analysis.AnalysisModels.*;

@Service
public class AnalysisService {
    public static final String ALGORITHM="chroma-baseline-v1";
    private final JdbcTemplate jdbc;private final ObjectMapper json;private final UUID owner;private final SongService songs;
    public AnalysisService(JdbcTemplate jdbc,ObjectMapper json,SongService songs,@Value("${strumlab.workspace-id:00000000-0000-4000-8000-000000000001}") UUID owner){this.jdbc=jdbc;this.json=json;this.owner=owner;this.songs=songs;}
    private void ownedSong(UUID id,boolean lock,boolean writing){var rows=jdbc.queryForList("SELECT status FROM song WHERE id=? AND owner_id=?"+(lock?" FOR UPDATE":""),id,owner);if(rows.isEmpty())throw new SongProblem(404,"Música não encontrada.");if(writing&&rows.getFirst().get("status").equals("archived"))throw new SongProblem(409,"Reabra a música antes de enviar/aplicar análise.");}
    private Asset asset(java.sql.ResultSet rs)throws java.sql.SQLException{return new Asset(rs.getObject("id",UUID.class),rs.getObject("song_id",UUID.class),rs.getString("extension"),rs.getString("mime"),rs.getString("rights_basis"),rs.getInt("size_bytes"),rs.getObject("duration_seconds",Double.class),rs.getString("status"),rs.getObject("created_at",java.time.OffsetDateTime.class));}
    private Asset owned(UUID id,boolean lock){var list=jdbc.query("SELECT a.id,a.song_id,a.extension,a.mime,a.rights_basis,a.size_bytes,a.duration_seconds,a.status,a.created_at FROM audio_asset a JOIN song s ON s.id=a.song_id WHERE a.id=? AND a.owner_id=? AND s.owner_id=?"+(lock?" FOR UPDATE OF a":""),(rs,n)->asset(rs),id,owner,owner);if(list.isEmpty())throw new SongProblem(404,"Áudio não encontrado.");return list.getFirst();}
    public List<Detail> list(UUID songId){ownedSong(songId,false,false);var values=jdbc.query("SELECT id,song_id,extension,mime,rights_basis,size_bytes,duration_seconds,status,created_at FROM audio_asset WHERE song_id=? AND owner_id=? ORDER BY (status='deleted'),created_at DESC LIMIT 20",(rs,n)->asset(rs),songId,owner);return values.stream().map(a->new Detail(a,jobs(a.id()))).toList();}
    private List<Job> jobs(UUID assetId){return jdbc.query("SELECT j.*,r.result_json FROM processing_job j LEFT JOIN analysis_result r ON r.job_id=j.id WHERE asset_id=? ORDER BY generation DESC",(rs,n)->new Job(rs.getObject("id",UUID.class),assetId,rs.getInt("generation"),rs.getString("status"),rs.getInt("attempts"),rs.getString("error_code"),rs.getString("algorithm_version"),rs.getObject("created_at",java.time.OffsetDateTime.class),rs.getObject("finished_at",java.time.OffsetDateTime.class),rs.getString("result_json")==null?null:json.readValue(rs.getString("result_json"),Result.class)),assetId);}
    public Detail detail(UUID id){var a=owned(id,false);return new Detail(a,jobs(id));}
    public Job job(UUID id){var ids=jdbc.queryForList("SELECT asset_id FROM processing_job WHERE id=?",UUID.class,id);if(ids.isEmpty())throw new SongProblem(404,"Análise não encontrada.");owned(ids.getFirst(),false);return jobs(ids.getFirst()).stream().filter(j->j.id().equals(id)).findFirst().orElseThrow();}
    public static String validate(byte[] bytes,String filename,String mime,String rights){if(bytes==null||bytes.length<44||bytes.length>20971520)throw new SongProblem(422,"Envie um arquivo de 44 bytes a 20 MiB.");if(!Set.of("own","permission","public_domain").contains(rights==null?"":rights))throw new SongProblem(422,"Declare autorização de uso do áudio.");String ext=filename==null?"":filename.substring(filename.lastIndexOf('.')+1).toLowerCase(Locale.ROOT);boolean wav=ext.equals("wav")&&new String(bytes,0,4,StandardCharsets.US_ASCII).equals("RIFF")&&new String(bytes,8,4,StandardCharsets.US_ASCII).equals("WAVE");boolean mp3=ext.equals("mp3")&&(new String(bytes,0,3,StandardCharsets.US_ASCII).equals("ID3")||((bytes[0]&255)==255&&(bytes[1]&224)==224));if(!(wav&&Set.of("audio/wav","audio/x-wav","audio/wave").contains(mime==null?"":mime))&&!(mp3&&Set.of("audio/mpeg","audio/mp3").contains(mime==null?"":mime)))throw new SongProblem(422,"Formato inválido. Envie WAV ou MP3 compatível com a extensão e MIME.");return ext;}
    @Transactional public Detail upload(UUID songId,byte[] bytes,String filename,String mime,String rights){String ext=validate(bytes,filename,mime,rights);ownedSong(songId,true,true);jdbc.queryForList("SELECT id FROM workspace WHERE id=? FOR UPDATE",owner);String hash;try{hash=HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(bytes));}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}var duplicate=jdbc.queryForList("SELECT id,status FROM audio_asset WHERE song_id=? AND sha256=?",songId,hash);if(!duplicate.isEmpty()){UUID id=(UUID)duplicate.getFirst().get("id");if(!duplicate.getFirst().get("status").equals("deleted"))return detail(id);throw new SongProblem(409,"Este áudio foi excluído. Envie outro arquivo; resultados anteriores permanecem para consulta.");}long total=jdbc.queryForObject("SELECT COALESCE(SUM(size_bytes),0) FROM audio_asset WHERE owner_id=? AND status<>'deleted'",Long.class,owner);int count=jdbc.queryForObject("SELECT COUNT(*) FROM audio_asset WHERE song_id=? AND status<>'deleted'",Integer.class,songId);if(total+bytes.length>104857600||count>=10)throw new SongProblem(422,"Limite local: 100 MiB por biblioteca e 10 áudios ativos por música.");UUID id=UUID.randomUUID();jdbc.update("INSERT INTO audio_asset(id,song_id,owner_id,sha256,extension,mime,rights_basis,size_bytes,audio_bytes) VALUES (?,?,?,?,?,?,?,?,?)",id,songId,owner,hash,ext,ext.equals("wav")?"audio/wav":"audio/mpeg",rights,bytes.length,bytes);jdbc.update("INSERT INTO processing_job(id,asset_id,generation,algorithm_version) VALUES (?,?,1,?)",UUID.randomUUID(),id,ALGORITHM);return detail(id);}
    @Transactional public Detail reprocess(UUID id,Reprocess request){var asset=owned(id,true);ownedSong(asset.songId(),false,true);if(asset.status().equals("deleted"))throw new SongProblem(409,"Áudio excluído; não pode ser reprocessado.");var latest=jobs(id).getFirst();if(!latest.id().equals(request.currentJobId()))throw new SongProblem(409,"Há uma análise mais recente. Recarregue.");if(Set.of("pending","processing").contains(latest.status()))return detail(id);if(latest.status().equals("failed")&&!request.reprocess()){if(latest.attempts()>=3)throw new SongProblem(409,"Limite de três tentativas atingido. Exclua o áudio inválido ou consulte o erro.");jdbc.update("UPDATE processing_job SET status='pending',error_code=NULL,finished_at=NULL,lease_token=NULL,lease_until=NULL WHERE id=?",latest.id());}
    else {if(!request.reprocess())throw new SongProblem(422,"Confirme reprocessamento explícito.");if(latest.generation()>=5)throw new SongProblem(422,"Limite local de cinco análises por áudio.");jdbc.update("INSERT INTO processing_job(id,asset_id,generation,algorithm_version) VALUES (?,?,?,?)",UUID.randomUUID(),id,latest.generation()+1,ALGORITHM);}return detail(id);}
    @Transactional public Detail delete(UUID id){owned(id,true);jdbc.update("UPDATE processing_job SET status='cancelled',lease_token=NULL,lease_until=NULL,finished_at=CURRENT_TIMESTAMP WHERE asset_id=? AND status IN ('pending','processing')",id);jdbc.update("UPDATE audio_asset SET audio_bytes=NULL,status='deleted',deleted_at=CURRENT_TIMESTAMP WHERE id=?",id);return detail(id);}
    public byte[] audio(UUID id){var a=owned(id,false);if(!a.status().equals("valid"))throw new SongProblem(409,"Áudio ainda não validado ou excluído.");return jdbc.queryForObject("SELECT audio_bytes FROM audio_asset WHERE id=?",byte[].class,id);}
    @Transactional public SongService.Detail apply(UUID jobId,Apply input){var job=job(jobId);var asset=owned(job.assetId(),false);ownedSong(asset.songId(),true,true);if(job.result()==null)throw new SongProblem(409,"Esta análise ainda não tem resultado.");if(input.requestKey()==null)throw new SongProblem(422,"Informe a chave da aplicação.");var previous=jdbc.queryForList("SELECT song_revision_id FROM analysis_acceptance WHERE job_id=? AND request_key=?",UUID.class,jobId,input.requestKey());if(!previous.isEmpty())return songs.detail(asset.songId());var detail=songs.detail(asset.songId());var c=detail.draft();if(!input.applyBpm()&&!input.applyKey()&&!input.applyChords())throw new SongProblem(422,"Selecione ao menos um campo.");Integer bpm=c.bpm();String key=c.key();var sections=new ArrayList<>(c.sections());if(input.applyBpm()){if(input.bpm()==null||input.bpm()<30||input.bpm()>300)throw new SongProblem(422,"BPM corrigido deve estar entre 30 e 300.");bpm=input.bpm();}if(input.applyKey()){if(input.key()==null||!input.key().matches("[A-G](#|b)?m?"))throw new SongProblem(422,"Informe uma tonalidade válida.");key=input.key();}if(input.applyChords()){validateEvents(input.chords(),job.result().duration());if(input.chords().isEmpty())throw new SongProblem(422,"Inclua ao menos um evento de acorde.");var lines=input.chords().stream().map(e->new SongContent.Line(UUID.randomUUID().toString(),List.of(new SongContent.Token("text",null,String.format(Locale.ROOT,"[%.2fs–%.2fs] ",e.start(),e.end())),new SongContent.Token("chord",e.chord(),null)))).toList();sections.add(new SongContent.Section(UUID.randomUUID().toString(),"other","Acordes do áudio · revisão humana",lines));}
        var updated=new SongContent(c.schemaVersion(),c.title(),c.artist(),key,bpm,c.meter(),c.capo(),c.sourceType(),c.sourceReference(),c.rightsBasis(),sections);var saved=songs.acceptAnalysis(asset.songId(),new SongService.Edit(updated,input.baseRevisionId(),input.draftVersion()));jdbc.update("INSERT INTO analysis_acceptance(id,job_id,request_key,song_revision_id,selection_json) VALUES (?,?,?,?,?::jsonb)",UUID.randomUUID(),jobId,input.requestKey(),saved.song().currentRevisionId(),json.writeValueAsString(input));return saved;}
    public static void validateEvents(List<ChordEvent> events,double duration){if(events==null||events.size()>1200)throw new SongProblem(422,"Até 1200 eventos por análise.");double previous=0;for(var e:events){if(e==null||!Double.isFinite(e.start())||!Double.isFinite(e.end())||e.start()<previous||e.end()<=e.start()||e.end()>duration+.01||e.chord()==null||!e.chord().matches("[A-G](#|b)?m?"))throw new SongProblem(422,"Eventos devem estar ordenados, sem sobreposição, com tempos e tríades válidos. Remova eventos N antes de aplicar.");previous=e.end();}}
}
